<template><Teleport to="body"><div v-if="open" class="modal-layer" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><button class="backdrop" type="button" aria-label="取消操作" @click="$emit('cancel')" /><section><span class="eyebrow">CONFIRM ADMIN ACTION</span><h2 id="confirm-title">{{ title }}</h2><p>{{ description }}</p><div v-if="guard" class="guard" role="alert">{{ guard }}</div><footer><button type="button" class="quiet" :disabled="busy" @click="$emit('cancel')">取消</button><button type="button" :class="{ danger }" :disabled="busy || Boolean(guard)" @click="$emit('confirm')">{{ busy ? '处理中…' : confirmText }}</button></footer></section></div></Teleport></template>
<script setup lang="ts">defineProps<{ open:boolean; title:string; description:string; confirmText:string; danger:boolean; busy:boolean; guard?:string }>(); defineEmits<{ cancel:[]; confirm:[] }>()</script>
<style scoped>.modal-layer{position:fixed;inset:0;z-index:4600;display:grid;place-items:center;padding:18px}.backdrop{position:absolute;inset:0;border:0;background:rgba(7,25,23,.58)}section{position:relative;width:min(440px,100%);box-sizing:border-box;padding:24px;border-radius:18px;background:#fff;box-shadow:0 25px 80px rgba(0,0,0,.25)}.eyebrow{color:#8a5a27;font-size:9px;letter-spacing:.14em}h2{margin:7px 0 8px;color:#173d36;font-size:21px}p{margin:0;color:#637570;font-size:12px;line-height:1.7}.guard{margin-top:14px;padding:11px;border-radius:10px;background:#fff0ec;color:#9d402f;font-size:11px}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}footer button{border:0;border-radius:9px;padding:9px 14px;background:#176b5a;color:#fff;font-weight:750;cursor:pointer}footer .quiet{background:#e7efec;color:#425e57}footer .danger{background:#a84532}footer button:disabled{cursor:not-allowed;opacity:.5}</style>
